static inline bool type_is8bitsize(uint8_t type) {
  uint8_t subcategory = type >> 4;
  return subcategory==0xA || subcategory==0xC || subcategory==0xE;
}

static inline bool type_isspecial(uint8_t type) {
  return (type >> 4) == 0x4;
